// BattleCruiser — 16.14: asignar presentaciones a productos.
(function(){'use strict';if(window.__BC1614)return;window.__BC1614=true;
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]})}
function permit(){return typeof tienePermiso==='function'&&(tienePermiso('presentaciones','crear')||tienePermiso('presentaciones','editar'))}
function install(){var box=document.getElementById('bc166-presentaciones');if(!box||document.getElementById('bc1614-asignacion')||!permit())return !!box;var sec=document.createElement('div');sec.id='bc1614-asignacion';sec.style.marginTop='16px';sec.innerHTML='<div class="rule-orn" style="margin:14px 0"></div><h4>Asignar presentación a producto</h4><p class="muted">Define qué presentación usa cada producto en compras y ventas y cuántas unidades base contiene.</p><div style="display:grid;grid-template-columns:1fr 1fr 140px auto;gap:8px;align-items:end"><label class="muted" style="font-size:11px">Producto<select id="bc1614-producto" style="width:100%"><option value="">Seleccionar…</option></select></label><label class="muted" style="font-size:11px">Presentación<select id="bc1614-pres" style="width:100%"><option value="">Seleccionar…</option></select></label><label class="muted" style="font-size:11px">Factor<input id="bc1614-factor" type="number" min="0.0001" step="any" placeholder="24"></label><button type="button" id="bc1614-save">Asignar</button></div><div id="bc1614-rel-lista" class="lista" style="margin-top:10px"></div><p id="bc1614-msg" class="msg"></p>';box.appendChild(sec);populate();document.getElementById('bc1614-save').onclick=save;refresh();return true;}
function populate(){var ps=(window._cache&&_cache.productos)||[],pres=[];try{pres=(window._cache&&_cache.presentaciones)||[]}catch(_){}if(!pres.length){client.from('presentaciones').select('id,nombre,activo').eq('activo',true).order('nombre').then(function(r){if(!r.error){if(typeof _cache!=='undefined')_cache.presentaciones=r.data||[];populate();}})}var p=document.getElementById('bc1614-producto'),s=document.getElementById('bc1614-pres');if(!p||!s)return;p.innerHTML='<option value="">Seleccionar…</option>'+ps.filter(function(x){return x.activo!==false}).map(function(x){return '<option value="'+esc(x.id)+'">'+esc(x.nombre)+'</option>'}).join('');s.innerHTML='<option value="">Seleccionar…</option>'+pres.filter(function(x){return x.activo!==false}).map(function(x){return '<option value="'+esc(x.id)+'">'+esc(x.nombre)+'</option>'}).join('');}
async function refresh(){var el=document.getElementById('bc1614-rel-lista');if(!el)return;try{var r=await client.from('producto_presentaciones').select('id,producto_id,presentacion_id,factor,activo,productos(nombre),presentaciones(nombre)').order('created_at',{ascending:false}).limit(100);if(r.error)throw r.error;el.innerHTML=(r.data||[]).map(function(x){return '<div class="lista-item"><span><strong>'+esc(x.productos?.nombre||'—')+'</strong> · '+esc(x.presentaciones?.nombre||'—')+' · ×'+Number(x.factor||0)+'</span><button type="button" data-rel="'+esc(x.id)+'" data-active="'+(x.activo?'1':'0')+'">'+(x.activo?'Desactivar':'Activar')+'</button></div>'}).join('')||'<p class="lista-estado">No hay asociaciones creadas.</p>';el.querySelectorAll('[data-rel]').forEach(function(b){b.onclick=function(){toggle(b.dataset.rel,b.dataset.active!=='1')}});}catch(e){el.innerHTML='<p class="lista-estado">No se pudo cargar las asociaciones.</p>';}}
async function save(){var pid=document.getElementById('bc1614-producto')?.value,prid=document.getElementById('bc1614-pres')?.value,f=Number(document.getElementById('bc1614-factor')?.value);if(!pid||!prid||!(f>0)){msg('Completa producto, presentación y factor.',false);return}try{var q=await client.from('producto_presentaciones').select('id,activo').eq('producto_id',pid).eq('presentacion_id',prid).order('created_at',{ascending:false}).limit(1);if(q.error)throw q.error;var row=q.data&&q.data[0];var r;if(row){r=await client.from('producto_presentaciones').update({factor:f,activo:true}).eq('id',row.id)}else{r=await client.from('producto_presentaciones').insert({producto_id:pid,presentacion_id:prid,factor:f,activo:true})}if(r.error)throw r.error;msg('Presentación asignada.',true);await refresh();}catch(e){msg(e.message||'No se pudo asignar.',false)}}
async function toggle(id,activo){try{var r=await client.from('producto_presentaciones').update({activo:activo}).eq('id',id);if(r.error)throw r.error;await refresh();}catch(e){msg(e.message||'No se pudo cambiar el estado.',false)}}
function msg(t,ok){var e=document.getElementById('bc1614-msg');if(e){e.textContent=t;e.className='msg '+(ok?'success':'error')}}
function boot(){if(install())return;[300,800,1500,3000].forEach(function(ms){setTimeout(install,ms)})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();window.__BC1614_verify=function(){return{assignmentPanel:!!document.getElementById('bc1614-asignacion'),productSelect:!!document.getElementById('bc1614-producto'),presentationSelect:!!document.getElementById('bc1614-pres')}};
})();